import type { StockPhoto, StockPhotoSearchRequest } from '@aglyn/aglyn/plugin-manager/stock-photo-provider'

/**
 * WHAT PIXABAY ANSWERED THE SEARCHES OF TWO TEST SITES ON 2026-10-29 (AGL-4092).
 *
 * The live check of beta.291 started two fictional businesses afresh in the
 * test workspace: Pit Row Tacos (a taco trailer at motocross races) and Rut
 * Runners Racing (an amateur motocross team). Their media libraries record
 * only the search that found each photo, so the searches themselves were
 * read back, read-only, from production's 24-hour search cache
 * (`stockPhotoSearches`, keyed by each request's canonical parameters):
 * every search the replay sends on the code that built them was there, so
 * production sent each of them, and the replay places what production
 * placed. Thirteen searches production never sent were asked of Pixabay,
 * read-only, the same day, as the provider asks them: those the fixes send
 * in place of production's, and those asked to choose them ("motocross
 * paddock" answers horses and "motocross pits" fruit, so a team asks
 * neither). Each comment says which.
 *
 * Each list is the first 20 hits of its answer, in its order; the six
 * answers in which a photo at issue stood past the 20th are kept whole (40).
 * A hit's tags are the provider's (up to 30); its size is its large copy's.
 * Each contributor is a number, one per contributor, so a shoot still reads
 * as one; no name, no contact details.
 *
 * A list is keyed by what was asked: its words, its orientation, its size
 * and, for a people search, "people" (`aiAgl40921029AnswerKey`).
 */

const hit = (id: number, width: number, height: number, slug: string, contributor: number, tags: string): StockPhoto =>
  ({
    provider: 'pixabay',
    id: String(id),
    width,
    height,
    pageUrl: `https://pixabay.com/photos/${slug}-${id}/`,
    photographer: `Pixabay contributor ${contributor}`,
    tags: tags.split(', ').filter(Boolean),
    downloadUrl: `https://pixabay.com/get/g${id}_1280.jpg`,
  }) as StockPhoto

